import express from 'express';
import sql from 'mssql';

const router = express.Router();

router.post('/api/calidad/inspecciones', async (req, res) => {
  const { ordenProduccion, linea, ectValor, ectMinimo, mullenPsi, humedadPct, inspector } = req.body;
  const conforme = Number(ectValor) >= Number(ectMinimo) && Number(humedadPct) <= 9.5;

  const pool = await sql.connect(process.env.SQL_CONNECTION_STRING);
  const result = await pool.request()
    .input('OrdenProduccion', sql.VarChar(30), ordenProduccion)
    .input('Linea', sql.VarChar(40), linea)
    .input('ECT', sql.Decimal(8, 2), ectValor)
    .input('Mullen', sql.Decimal(8, 2), mullenPsi)
    .input('Humedad', sql.Decimal(5, 2), humedadPct)
    .input('Estado', sql.VarChar(20), conforme ? 'APROBADO' : 'RETENIDO_REVISION')
    .input('Inspector', sql.VarChar(60), inspector)
    .execute('sp_RegistrarInspeccionCalidad');

  return res.status(201).json({
    inspeccionId: result.recordset[0].InspeccionID,
    estado: conforme ? 'APROBADO' : 'RETENIDO_REVISION',
    certificadoEmitido: conforme
  });
});

export default router;
